try:
    import pdfplumber
except ImportError:
    pdfplumber = None

try:
    from nltk.corpus import stopwords, wordnet as wn
except ImportError:
    print("Missing nltk. Run: pip install nltk --break-system-packages", file=sys.stderr)
    raise

try:
    STOPWORDS = set(stopwords.words("english"))
except LookupError:
    print("Missing nltk data. Run:\n"
          "  python3 -c \"import nltk; nltk.download('stopwords'); "
          "nltk.download('wordnet'); nltk.download('omw-1.4')\"", file=sys.stderr)
    raise

EXTRA_STOPWORDS = {
    "et", "al", "fig", "figure", "table", "doi", "pp", "vol", "no",
    "et al", "ie", "eg", "etc", "http", "https", "www", "com",
    "copyright", "press", "journal", "vol.", "pp.",
}
WORD_RE = re.compile(r"[a-zA-Z][a-zA-Z\-]+[a-zA-Z]")

# pdfplumber emits "(cid:123)" wherever a glyph has no Unicode mapping (ligatures,
# math symbols). Left in, "cid" becomes the single most frequent "word" in the corpus.
CID_RE = re.compile(r"\(\s*cid\s*:\s*\d+\s*\)")

VOCAB_SIDECAR = Path(__file__).with_name("vocab.json")
# The unpruned corpus. Pruning drops bigrams, but LLM candidates are often phrases,
# so frequency lookups use this when it exists.
VOCAB_FULL_SIDECAR = Path(__file__).with_name("vocab.full.json")

DEFAULT_LLM_MODEL = "gpt-5.6-luna"
KEY_FILE = Path(__file__).with_name("conf")
LLM_SYSTEM_PROMPT = (
    "You suggest replacement wordings for academic prose. Given a word and optional "
    "surrounding sentence, propose precise alternatives that fit formal research writing. "
    "Prefer plain, direct academic register over ornate synonyms. Include multi-word "
    "phrasings where they read better. Never repeat the input word. Give a short reason "
    "naming the nuance that distinguishes each candidate."
)


def _load_embedded_vocab():
    """Decode the vocabulary that's baked into this file."""
    raw = base64.b85decode(_VOCAB_B85.encode("ascii"))
    data = gzip.decompress(raw)
    return json.loads(data)


def extract_text_from_pdfs(pdf_dir, x_tolerance=1.5, min_chars=1000):
    """Extract raw text from every PDF in a directory. Returns dict {filename: text}.

    x_tolerance is the character gap (in points) above which pdfplumber inserts a
    space. Its default of 3 is too wide for many tightly-set academic PDFs and
    silently glues words together ("JournalofMachineLearningResearch"), which
    poisons the vocabulary with junk terms. 1.5 splits those correctly without
    breaking up normal words.

    PDFs yielding less than min_chars are almost always image-only scans with no
    text layer; they are skipped with a warning rather than contributing nothing.
    """
    if pdfplumber is None:
        print("pdfplumber is required to build from PDFs. "
              "Run: pip install pdfplumber --break-system-packages", file=sys.stderr)
        sys.exit(1)
    pdf_dir = Path(pdf_dir)
    texts = {}
    pdf_files = sorted(pdf_dir.glob("*.pdf"))
    if not pdf_files:
        print(f"No PDFs found in {pdf_dir}", file=sys.stderr)
    for pdf_path in pdf_files:
        print(f"Reading {pdf_path.name} ...")
        pages_text = []
        try:
            with pdfplumber.open(pdf_path) as pdf:
                for page in pdf.pages:
                    t = page.extract_text(x_tolerance=x_tolerance) or ""
                    pages_text.append(t)
        except Exception as e:
            print(f"  Failed to read {pdf_path.name}: {e}", file=sys.stderr)
            continue
        text = "\n".join(pages_text)
        if len(text) < min_chars:
            print(f"  Skipping {pdf_path.name}: only {len(text)} chars of text "
                  f"(likely a scanned image with no text layer).", file=sys.stderr)
            continue
        texts[pdf_path.name] = text
    return texts


def clean_text(text):
    """Fix PDF line-break hyphenation artifacts and normalize whitespace."""
    text = re.sub(r"(\w)-\s*\n\s*(\w)", r"\1\2", text)
    text = CID_RE.sub(" ", text)
    text = re.sub(r"\s+", " ", text)
    return text


def tokenize(text):
    """Lowercase, extract word tokens, drop stopwords/short/numeric junk."""
    tokens = WORD_RE.findall(text.lower())
    out = []
    for tok in tokens:
        tok = tok.strip("-")
        if len(tok) < 3:
            continue
        if tok in STOPWORDS or tok in EXTRA_STOPWORDS:
            continue
        out.append(tok)
    return out


def build_ngrams(tokens, n):
    return [" ".join(tokens[i:i + n]) for i in range(len(tokens) - n + 1)]


def build_vocabulary(texts, ngram_sizes=(1, 2)):
    """Build frequency counters (unigrams, bigrams) plus document frequency."""
    freq = Counter()
    doc_freq = Counter()
    per_doc_word_counts = {}

    for fname, raw_text in texts.items():
        text = clean_text(raw_text)
        tokens = tokenize(text)
        per_doc_word_counts[fname] = len(tokens)

        doc_terms = set()
        for n in ngram_sizes:
            grams = build_ngrams(tokens, n) if n > 1 else tokens
            freq.update(grams)
            doc_terms.update(grams)
        doc_freq.update(doc_terms)

    return {
        "term_freq": dict(freq),
        "doc_freq": dict(doc_freq),
        "num_docs": len(texts),
        "doc_names": list(texts.keys()),
        "doc_word_counts": per_doc_word_counts,
    }


def merge_vocabs(base, new):
    """Add `new`'s counts into `base`, returning a fresh vocabulary.

    Term and document frequencies are additive across *disjoint* document sets,
    so any document already present in `base` (matched by filename) is dropped
    from the merge -- otherwise re-running a build would double-count it.
    Note this only skips whole documents; it cannot un-count a paper that was
    added earlier under a different filename.
    """
    duplicates = [d for d in new["doc_names"] if d in set(base["doc_names"])]
    if duplicates:
        print(f"Skipping {len(duplicates)} document(s) already in the base vocabulary: "
              f"{', '.join(duplicates)}", file=sys.stderr)
        if len(duplicates) == len(new["doc_names"]):
            return dict(base)
        raise SystemExit(
            "Refusing to merge: the new build mixes already-counted documents with new "
            "ones, and per-document counts are not retained, so the duplicates cannot be "
            "subtracted out. Re-run the build on a folder holding only the new PDFs."
        )

    term_freq = Counter(base["term_freq"])
    term_freq.update(new["term_freq"])
    doc_freq = Counter(base["doc_freq"])
    doc_freq.update(new["doc_freq"])

    return {
        "term_freq": dict(term_freq),
        "doc_freq": dict(doc_freq),
        "num_docs": base["num_docs"] + new["num_docs"],
        "doc_names": list(base["doc_names"]) + list(new["doc_names"]),
        "doc_word_counts": {**base["doc_word_counts"], **new["doc_word_counts"]},
    }


def impact_score(count, docs):
    """Rank a term by usefulness as writing vocabulary.

    Frequency alone over-rewards jargon that spikes in a single paper. Weighting by
    how many papers use the term favours the general academic register that carries
    across your own writing, which is what a synonym aid is for.
    """
    return count * (1.0 + math.log(1 + docs))


def prune_vocab(vocab, strategy="suggestible", fraction=0.10):
    """Shrink a vocabulary to the terms that actually earn their place.

    Strategies:
      suggestible -- keep single-word terms present in WordNet. These are the ONLY
                     terms suggest_synonyms can ever return, so dropping the rest
                     costs no synonym coverage at all.
      unigrams    -- keep every single-word term. Strictly lossless for `suggest`
                     (which never reads bigrams), just less aggressive.
      impact      -- keep the top `fraction` of terms by impact_score, bigrams
                     included. Smallest and best for `top`, but it WILL drop real
                     corpus words, after which `suggest` reports them as absent.
    """
    tf, df = vocab["term_freq"], vocab["doc_freq"]
    if strategy == "unigrams":
        keep = {t for t in tf if " " not in t}
    elif strategy == "suggestible":
        keep = {t for t in tf if " " not in t and wn.synsets(t)}
    elif strategy == "impact":
        ranked = sorted(tf, key=lambda t: -impact_score(tf[t], df.get(t, 0)))
        keep = set(ranked[:max(1, int(len(ranked) * fraction))])
    else:
        raise ValueError(f"unknown strategy: {strategy}")

    return {
        **vocab,
        "term_freq": {t: c for t, c in tf.items() if t in keep},
        "doc_freq": {t: c for t, c in df.items() if t in keep},
    }


def save_vocab(vocab, path):
    with open(path, "w") as f:
        json.dump(vocab, f, indent=1)
    print(f"Saved vocabulary ({len(vocab['term_freq'])} terms from "
          f"{vocab['num_docs']} papers) to {path}")


def prune_cid_terms(vocab):
    """Drop "cid" glyph-placeholder terms from a vocabulary built before CID_RE existed.

    The embedded vocabulary was built without that filter and its source PDFs are no
    longer around to rebuild from, so the junk is stripped at load time instead.
    doc_word_counts is left alone -- it is reporting metadata, not used in ranking.
    """
    junk = {t for t in vocab["term_freq"] if "cid" in t.split()}
    if not junk:
        return vocab
    return {
        **vocab,
        "term_freq": {t: c for t, c in vocab["term_freq"].items() if t not in junk},
        "doc_freq": {t: c for t, c in vocab["doc_freq"].items() if t not in junk},
    }


def load_vocab(explicit_path=None):
    """Load vocabulary: explicit --vocab path > sidecar vocab.json > embedded default."""
    if explicit_path:
        with open(explicit_path) as f:
            return prune_cid_terms(json.load(f))
    if VOCAB_SIDECAR.exists():
        with open(VOCAB_SIDECAR) as f:
            return prune_cid_terms(json.load(f))
    return prune_cid_terms(_load_embedded_vocab())


def load_lookup_vocab(explicit_path=None):
    """Vocabulary used to look up how often a candidate appears in your papers.

    Prefers the unpruned vocab.full.json: `prune` strips bigrams, and LLM candidates
    are frequently phrases that only exist there. Falls back to the normal chain.
    """
    if explicit_path is None and VOCAB_FULL_SIDECAR.exists():
        with open(VOCAB_FULL_SIDECAR) as f:
            return prune_cid_terms(json.load(f))
    return load_vocab(explicit_path)


def normalize_candidate(term):
    """Map a candidate onto the corpus's own token form so lookups can match.

    Vocabulary n-grams are built from stopword-filtered tokens, so "make use of" is
    stored as "make use". Looking up the raw phrase would always miss.
    """
    return " ".join(tokenize(term))


def _openai_api_key():
    """API key from OPENAI_API_KEY, else the first sk- token in the sibling conf file."""
    key = os.getenv("OPENAI_API_KEY")
    if key and key.strip():
        return key.strip()
    if KEY_FILE.exists():
        match = re.search(r"sk-[A-Za-z0-9_\-]{20,}", KEY_FILE.read_text())
        if match:
            return match.group(0)
    return None


def get_llm_candidates(word, context=None, model=DEFAULT_LLM_MODEL, n=10):
    """Ask an OpenAI model for replacement wordings. Returns {term: reason}.

    Returns {} after printing a warning if the SDK, key, or network is unavailable --
    the corpus-backed path is the product and must keep working offline.
    """
    try:
        from openai import OpenAI
    except ImportError:
        print("openai package not installed; skipping LLM. Run: pip install openai",
              file=sys.stderr)
        return {}
    key = _openai_api_key()
    if not key:
        print(f"No OpenAI key found (set OPENAI_API_KEY or put it in {KEY_FILE.name}); "
              "skipping LLM.", file=sys.stderr)
        return {}

    schema = {
        "type": "object", "additionalProperties": False,
        "properties": {"candidates": {
            "type": "array", "items": {
                "type": "object", "additionalProperties": False,
                "properties": {"term": {"type": "string"}, "why": {"type": "string"}},
                "required": ["term", "why"]}}},
        "required": ["candidates"],
    }
    prompt = f"Word: '{word}'."
    if context:
        prompt += f" Context: '{context}'"
    prompt += f" Propose up to {n} alternatives."

    try:
        response = OpenAI(api_key=key).responses.create(
            model=model,
            reasoning={"effort": "low"},
            max_output_tokens=2000,
            input=[{"role": "developer", "content": LLM_SYSTEM_PROMPT},
                   {"role": "user", "content": prompt}],
            text={"format": {"type": "json_schema", "name": "candidates",
                             "strict": True, "schema": schema}},
        )
        data = json.loads(response.output_text)
    except Exception as e:
        print(f"LLM call failed ({type(e).__name__}: {e}); falling back to WordNet only.",
              file=sys.stderr)
        return {}

    out = {}
    for item in data.get("candidates", []):
        term = item["term"].strip().lower()
        if term and term != word.lower().strip():
            out[term] = item["why"].strip()
    return out


def get_wordnet_synonyms(word, max_senses=None):
    """Pull candidate single-word synonyms from WordNet.

    max_senses limits how many synsets are consulted. WordNet orders them roughly by
    frequency, so unioning all of them drags in far-fetched readings -- "number" is a
    synonym of "act" only in the theatrical sense. Suggestion mode can afford the full
    union because a human picks; automatic rewriting cannot.
    """
    word_norm = word.lower().strip()
    synonyms = set()
    senses = wn.synsets(word_norm)
    for syn in (senses[:max_senses] if max_senses else senses):
        for lemma in syn.lemmas():
            name = lemma.name().replace("_", " ")
            if name.lower() != word_norm and " " not in name:
                synonyms.add(name.lower())
    return synonyms


def suggest_synonyms(word, vocab, top_n=8, llm_candidates=None):
    """Rank candidate replacements for `word` by how often your papers use them.

    WordNet supplies single-word synonyms; `llm_candidates` ({term: reason}) optionally
    adds context-aware and multi-word ones. Both streams are looked up against the same
    corpus counts, so the ranking stays grounded in your own writing rather than the
    model's preferences. Each result carries the sources that proposed it.
    """
    term_freq = vocab["term_freq"]
    doc_freq = vocab["doc_freq"]
    llm_candidates = llm_candidates or {}

    sources = {}
    for cand in get_wordnet_synonyms(word):
        sources.setdefault(cand, set()).add("wordnet")
    for cand in llm_candidates:
        sources.setdefault(cand, set()).add("llm")

    found, unseen = [], []
    for cand, srcs in sources.items():
        lookup = normalize_candidate(cand)
        count = term_freq.get(lookup, 0)
        docs = doc_freq.get(lookup, 0)
        entry = (cand, count, docs, sorted(srcs), llm_candidates.get(cand, ""))
        (found if count > 0 else unseen).append(entry)

    found.sort(key=lambda x: (-x[1], x[0]))
    unseen.sort(key=lambda x: (x[0] not in llm_candidates, x[0]))
    return {
        "found": found[:top_n],
        "unseen": unseen[:top_n],
        "input_word_freq": term_freq.get(normalize_candidate(word) or word.lower(), 0),
    }


def top_terms(vocab, n=30, min_docs=1):
    term_freq = vocab["term_freq"]
    doc_freq = vocab["doc_freq"]
    items = [(t, c) for t, c in term_freq.items() if doc_freq.get(t, 0) >= min_docs]
    items.sort(key=lambda x: -x[1])
    return items[:n]


# Environments whose bodies are never prose.
LATEX_OPAQUE_ENVS = ("equation", "equation*", "align", "align*", "gather", "gather*",
                     "eqnarray", "eqnarray*", "verbatim", "lstlisting", "minted",
                     "tikzpicture", "algorithmic", "algorithm2e", "math", "displaymath")
# Commands whose braced argument is a key/path/identifier, not prose.
LATEX_OPAQUE_CMDS = ("cite", "citep", "citet", "citeauthor", "citeyear", "ref", "eqref",
                     "autoref", "cref", "Cref", "label", "url", "href", "includegraphics",
                     "usepackage", "documentclass", "bibliography", "bibliographystyle",
                     "input", "include", "newcommand", "renewcommand", "def", "def*",
                     "definecolor", "hypersetup", "setlength", "lstset", "acmConference",
                     "acmDOI", "acmISBN", "orcid", "email", "affiliation", "keywords",
                     "ccsdesc", "begin", "end")

# Rewriting a whole sentence is far less forgiving than swapping one word, so those
# modes additionally freeze grid environments (a stray & breaks the column count) and
# inline formatting commands together with their argument (so no loose brace escapes
# into the rewritten text).
SENTENCE_SAFE_ENVS = ("tabular", "tabularx", "longtable", "array", "matrix")

# Environments from common formal-methods packages whose bodies are specification
# source, not prose. tlatex.sty's `notla` holds raw TLA+ ("turn = \"input\""), where
# ordinary-looking words are identifiers: rewriting one silently changes the spec.
# Extend from the command line with --opaque-env for a paper's own environments.
FORMAL_ENVS = ("tlatex", "notla", "display", "noj", "conj", "popup", "pf", "proof",
               "lstlisting", "Verbatim", "alltt", "code", "spec")
SENTENCE_SAFE_CMDS = ("emph", "textbf", "textit", "texttt", "textsc", "mbox",
                      "underline", "footnote", "caption", "textsuperscript")


def _build_mask_re(extra_envs=(), extra_cmds=()):
    envs = "|".join(re.escape(e) for e in LATEX_OPAQUE_ENVS + tuple(extra_envs))
    cmds = "|".join(re.escape(c) for c in LATEX_OPAQUE_CMDS + tuple(extra_cmds))
    return re.compile(
        r"(?<!\\)%.*?$"                                          # comments
        # Backreference, not a second alternation: with (?:envs)...(?:envs) a nested
        # \begin{display}...\begin{notla}...\end{notla} closed at the wrong \end,
        # leaving the rest of the outer body exposed as prose.
        r"|\\begin\{(?P<env>" + envs + r")\}.*?\\end\{(?P=env)\}"
        r"|\$\$.*?\$\$|(?<!\\)\$.*?(?<!\\)\$"                    # math
        r"|\\\[.*?\\\]|\\\(.*?\\\)"
        r"|\\(?:" + cmds + r")\s*(?:\[[^\]]*\])?\s*\{[^{}]*\}"
        r"|\\[a-zA-Z@]+\*?",                                     # any remaining command
        re.DOTALL | re.MULTILINE)


_MASK_RE = _build_mask_re()


def mask_latex(text, extra_envs=(), extra_cmds=()):
    """Replace every non-prose LaTeX span with an inert placeholder.

    Returns (masked_text, spans). Placeholders use NUL bytes so they can never be
    matched by WORD_RE (which requires letters) or collide with document content.
    Restoring is a straight index lookup, so the output differs from the input only
    where a word was deliberately replaced.
    """
    spans = []
    mask_re = _build_mask_re(extra_envs, extra_cmds) if (extra_envs or extra_cmds) else _MASK_RE

    def stash(match):
        spans.append(match.group(0))
        return f"\x00{len(spans) - 1}\x00"

    # The preamble is configuration, never prose. Left exposed, package options and
    # colour definitions ("positioning", "RGB") reach the tokenizer as ordinary words
    # and a substitution there would break compilation rather than reword anything.
    start = text.find(r"\begin{document}")
    if start == -1:
        return mask_re.sub(stash, text), spans
    preamble = stash(re.match(re.escape(text[:start]), text[:start]))
    return preamble + mask_re.sub(stash, text[start:]), spans


def unmask_latex(text, spans):
    return re.sub(r"\x00(\d+)\x00", lambda m: spans[int(m.group(1))], text)


# Words that under-specify: they stand in for a precise action, object, or quality that
# the sentence usually already implies. These are the targets, not long words. Length
# is not the problem. Vagueness is, and the fix is often a longer, more exact word.
VAGUE_VERBS = (
    "utilize", "utilise", "leverage", "facilitate", "perform", "conduct", "handle",
    "address", "involve", "support", "provide", "enable", "achieve", "obtain",
    "carry", "undertake", "implement", "process", "manage", "apply", "affect",
    "impact", "improve", "enhance", "ensure", "capture", "reflect", "exhibit",
)
VAGUE_NOUNS = (
    "aspect", "aspects", "factor", "factors", "element", "elements", "component",
    "components", "issue", "issues", "thing", "things", "area", "areas", "way",
    "ways", "mechanism", "mechanisms", "process", "processes", "approach",
    "approaches", "capability", "capabilities", "functionality", "nature",
    "characteristic", "characteristics", "property", "properties", "behavior",
)
VAGUE_QUALIFIERS = (
    "various", "certain", "appropriate", "several", "significant", "substantial",
    "effective", "efficient", "robust", "novel", "key", "important", "relevant",
    "considerable", "notable", "meaningful", "reasonable", "suitable", "proper",
    "somewhat", "relatively", "fairly", "quite", "rather", "generally", "typically",
)
# A nominalization hides the verb that names the action ("the classification of X"
# rather than "classifying X"), so the reader reconstructs what happened.
NOMINALIZATION_RE = re.compile(r"\w{5,}(?:tion|sion|ment|ance|ence|ity|ization|isation)s?$")


def shortlist_precision(masked_text):
    """Find wording that is vaguer than the sentence around it needs.

    Deliberately corpus-independent, and deliberately not length-based: the aim is a
    word that names exactly what happens, which is frequently longer than the vague
    one it replaces. Returns {surface_form: reason}.
    """
    out = {}
    present = set(tokenize(masked_text))
    for group, reason in ((VAGUE_VERBS, "vague verb"),
                          (VAGUE_NOUNS, "vague noun"),
                          (VAGUE_QUALIFIERS, "vague qualifier")):
        for word in group:
            if word in present:
                out[word] = reason
    # Only flag a nominalization inside the frame that actually buries a verb ("the
    # classification of spans"). Flagging every -tion word instead swept in terms of art
    # (correlation, reliability, optimization) where a swap loses precision, and
    # measured 11% useful against 30% for the curated list above.
    for word in present:
        if word in out or not NOMINALIZATION_RE.match(word):
            continue
        if re.search(rf"\b(?:the|its|their|this)\s+{re.escape(word)}\s+of\b",
                     masked_text, re.IGNORECASE):
            out[word] = "nominalization (hides the verb)"
    return out


# A "concept" here is one clause making one claim. These are the joints where English
# bolts another clause on: each one past the first adds a concept the reader must hold.
CLAUSE_MARKERS = (
    "and", "or", "but", "while", "whereas", "although", "though", "because", "since",
    "unless", "until", "when", "where", "whether", "which", "that", "who", "whom",
    "without", "despite", "if", "so", "yet", "as",
)
_ABBREV = ("et al.", "i.e.", "e.g.", "cf.", "vs.", "Fig.", "Eq.", "Sec.", "Tab.",
           "approx.", "Dr.", "Mr.", "Ms.", "St.", "no.", "pp.")


def split_sentences(masked_text):
    """Yield (start, end, text) for each sentence in the masked body.

    Abbreviations are shielded first so "et al." does not end a sentence.
    """
    shielded = masked_text
    for abbrev in _ABBREV:
        shielded = shielded.replace(abbrev, abbrev.replace(".", "\x01"))
    out = []
    for match in re.finditer(r"[^.!?]+(?:[.!?]+|$)", shielded):
        start, end = match.start(), match.end()
        text = masked_text[start:end]
        if text.strip():
            out.append((start, end, text))
    return out


def count_concepts(sentence):
    """Approximate how many claims a sentence asks the reader to hold at once."""
    words = re.findall(r"[a-zA-Z]+", sentence.lower())
    joints = sum(1 for w in words if w in CLAUSE_MARKERS)
    joints += sentence.count(";") + sentence.count(":")
    return 1 + joints


def comment_span_ids(spans):
    """Placeholder ids whose masked span is a LaTeX comment.

    A comment placeholder stands for "%...", up to but not including the newline that
    ends it. If a rewrite reorders text across one, prose that used to sit on the next
    line lands on the comment line and is silently commented out of the PDF. Sentences
    spanning a comment are therefore left alone.
    """
    return {str(i) for i, s in enumerate(spans) if s.lstrip().startswith("%")}


def _spans_a_comment(text, comment_ids):
    return any(g in comment_ids for g in re.findall(r"\x00(\d+)\x00", text))


def shortlist_sentences(masked_text, max_concepts=3, min_words=12, comment_ids=()):
    """Sentences carrying more concepts than a reader can hold in one pass.

    Sentences containing a stray brace are skipped: those sit inside a command
    argument (a heading or similar) where wholesale rewriting is not safe.
    """
    out = []
    for start, end, text in split_sentences(masked_text):
        words = re.findall(r"[a-zA-Z]+", re.sub(r"\x00\d+\x00", " ", text))
        if len(words) < min_words or "{" in text or "}" in text:
            continue
        if _spans_a_comment(text, comment_ids):
            continue
        concepts = count_concepts(text)
        if concepts > max_concepts:
            out.append((start, end, text, concepts))
    return out


# Contrastive framing defines a thing by what it is not, forcing the reader to hold the
# rejected version in mind alongside the real one. The last two patterns are the hard
# case: the negation's complement is elided and lives in the previous sentence
# ("The response is uniform. Its three clauses are not."), so neither the detector nor
# the rewriter can work one sentence at a time.
CONTRAST_PATTERNS = (
    (r"\bnot\b[^.;]{0,90}?\bbut\b", "not X but Y"),
    (r"\bnot only\b[^.;]{0,90}?\bbut\b", "not only X but also Y"),
    (r"\brather than\b", "rather than"),
    (r"\binstead of\b", "instead of"),
    (r"\bas opposed to\b", "as opposed to"),
    (r"\bfar from\b", "far from"),
    (r"\bis no fix\b|\bis not the point\b|\bis not a\b|\bis not the\b|\bare not the\b",
     "negative definition"),
    (r"\bless\b[^.;]{0,60}\bthan\b", "less-than contrast"),
    (r"^\s*(?:Instead|Rather|However|Yet|But|By contrast|On the contrary|Conversely)\b",
     "contrastive opener"),
    (r"\b(?:is|are|was|were|do|does|did|has|have|can|could|will|would|should)\s+not\s*[.;]",
     "elided negation (complement is in the previous sentence)"),
    (r"^\s*(?:Not|Nor)\b", "sentence-initial negation"),
)


def detect_contrast(sentence):
    """Name the contrastive construction in a sentence, or None."""
    for pattern, name in CONTRAST_PATTERNS:
        if re.search(pattern, sentence, re.IGNORECASE | re.MULTILINE):
            return name
    return None


def shortlist_contrast(masked_text, comment_ids=()):
    """Find contrastive sentences, each paired with the sentence before it.

    The preceding sentence is carried along because an elided negation cannot be
    rewritten without it -- "Its three clauses are not" says nothing on its own.
    """
    out = []
    sentences = split_sentences(masked_text)
    for i, (start, end, text) in enumerate(sentences):
        if "{" in text or "}" in text or _spans_a_comment(text, comment_ids):
            continue
        reason = detect_contrast(text)
        if reason:
            out.append((start, end, text, reason, sentences[i - 1][2] if i else ""))
    return out


def shortlist_revisions(masked_text, vocab, rare_max=2, min_support=5, min_docs=2,
                        max_senses=2):
    """Find words in the manuscript that your corpus would phrase differently.

    A word is a candidate when the paper uses it but your own papers barely do
    (<= rare_max), while some WordNet synonym of it is well attested (>= min_support
    occurrences across >= min_docs papers). Returns {word: [(syn, count, docs), ...]}.
    """
    tf, df = vocab["term_freq"], vocab["doc_freq"]
    out = {}
    for word in sorted(set(tokenize(masked_text))):
        if tf.get(word, 0) > rare_max:
            continue
        backed = [(s, tf.get(s, 0), df.get(s, 0))
                  for s in get_wordnet_synonyms(word, max_senses=max_senses)]
        backed = [b for b in backed if b[1] >= min_support and b[2] >= min_docs]
        if backed:
            out[word] = sorted(backed, key=lambda x: -x[1])
    return out


def _sentence_for(text, match):
    """The sentence around a match, for showing the model what it is editing."""
    start = max(text.rfind(". ", 0, match.start()), text.rfind("\n\n", 0, match.start()))
    end = text.find(". ", match.end())
    snippet = text[(start + 1 if start > 0 else 0):(end + 1 if end > 0 else len(text))]
    return re.sub(r"\s+", " ", re.sub(r"\x00\d+\x00", " ", snippet)).strip()[:400]


def llm_screen_revisions(proposals, model=DEFAULT_LLM_MODEL, batch_size=60, goal="register"):
    """Ask the model which proposed substitutions are safe *in their sentence*.

    Corpus frequency says a word is off-register; only context says whether swapping
    it preserves meaning. Returns {(word, sentence): replacement_or_None}. On any
    failure returns {} so the caller can fall back to changing nothing.
    """
    try:
        from openai import OpenAI
    except ImportError:
        print("openai package not installed; skipping LLM screen.", file=sys.stderr)
        return {}
    key = _openai_api_key()
    if not key:
        print("No OpenAI key; skipping LLM screen.", file=sys.stderr)
        return {}

    schema = {
        "type": "object", "additionalProperties": False,
        "properties": {"decisions": {"type": "array", "items": {
            "type": "object", "additionalProperties": False,
            "properties": {"id": {"type": "integer"},
                           "replace": {"type": "boolean"},
                           "replacement": {"type": "string"},
                           "why": {"type": "string"}},
            "required": ["id", "replace", "replacement", "why"]}}},
        "required": ["decisions"],
    }
    REGISTER = (
        "You are copy-editing an academic manuscript to match the author's own corpus. "
        "For each item, decide whether replacing `word` with one of `options` in that "
        "sentence preserves the exact technical meaning and reads naturally. "
        "Set replace=false unless you are confident; a wrong substitution is far worse "
        "than a missed improvement. Never change a term of art, a defined construct, or "
        "a word whose meaning is load-bearing for the claim. Match the original's "
        "grammatical form (tense, number). Choose only from `options`."
    )
    PRECISE = (
        "You are making an academic paper easier to understand by making it MORE "
        "PRECISE. A reader understands faster when a word names exactly what happens, "
        "not when the word is shorter or more common.\n"
        "For each item, `word` is vague. Replace it with the most exact wording the "
        "surrounding sentence supports: name the actual operation, object, or quality. "
        "Turn hidden nouns back into verbs ('classifying spans', not 'the "
        "classification of spans').\n"
        "HARD RULES:\n"
        "1. NEVER replace a word with a more general one. Going from 'adjusts' to "
        "'sets', or 'renders' to 'provides', is a failure -- reject those outright.\n"
        "2. A longer, more specific word beats a shorter, vaguer one. Do not simplify.\n"
        "3. Use ONLY information already present in the sentence. Never invent a "
        "specific -- no numbers, mechanisms, or claims the text does not state.\n"
        "4. Set replace=false if the sentence lacks the detail needed to be more "
        "precise, or if the word is a term of art, a defined construct, or already "
        "exact. Rejecting is correct whenever precision cannot be increased.\n"
        "You are NOT limited to `options`; they are weak hints and usually too general. "
        "Match the grammatical form of the original exactly."
    )
    instructions = PRECISE if goal == "precise" else REGISTER
    client = OpenAI(api_key=key)
    decisions = {}
    # Batched: a whole manuscript's worth of sites overflows one response, and a
    # truncated reply would silently drop every decision after the cut.
    for begin in range(0, len(proposals), batch_size):
        chunk = proposals[begin:begin + batch_size]
        items = [{"id": begin + i, "word": w, "sentence": s, "options": [o[0] for o in opts]}
                 for i, (w, s, opts) in enumerate(chunk)]
        try:
            response = client.responses.create(
                model=model, reasoning={"effort": "medium"}, max_output_tokens=16000,
                input=[{"role": "developer", "content": instructions},
                       {"role": "user", "content": json.dumps(items, ensure_ascii=False)}],
                text={"format": {"type": "json_schema", "name": "decisions",
                                 "strict": True, "schema": schema}},
            )
            data = json.loads(response.output_text)
        except Exception as e:
            print(f"  batch {begin // batch_size + 1} failed ({type(e).__name__}: {e}); "
                  "those sites are left unchanged.", file=sys.stderr)
            continue
        for d in data.get("decisions", []):
            if not d["replace"] or not (0 <= d["id"] < len(proposals)):
                continue
            word, sentence, opts = proposals[d["id"]]
            replacement = d["replacement"].strip().lower()
            if goal == "precise":
                # Free-form text goes straight into a .tex file, so reject anything
                # carrying LaTeX syntax or line breaks before it can corrupt the source.
                if re.search(r"[\\{}$%&#_^~\x00\n\r]", replacement) or len(replacement) > 60:
                    continue
                if not replacement or replacement == word.lower():
                    continue
                # Enforce rule 1 mechanically: swapping one vague word for another is
                # the exact failure mode that produced "adjust -> set" earlier.
                if replacement in VAGUE_VERBS + VAGUE_NOUNS + VAGUE_QUALIFIERS:
                    continue
            elif replacement not in {o[0] for o in opts}:
                continue
            decisions[(word, sentence)] = (replacement, d["why"])
        print(f"  screened {min(begin + batch_size, len(proposals))}/{len(proposals)} "
              f"sites, {len(decisions)} accepted so far")
    return decisions


# After a modal or infinitive "to", English requires the bare verb form.
_BARE_FORM_TRIGGERS = frozenset((
    "would", "will", "can", "could", "may", "might", "must", "should", "shall",
    "to", "cannot", "don't", "doesn't", "didn't", "help", "let", "make",
))


def _fix_agreement(masked, start, replacement):
    """Repair the one inflection error the model reliably makes.

    Asked to swap "provide" in "Point C would provide", it returns "delivers" and
    yields "would delivers". Dropping the -s after a modal is always right in English,
    so fix it rather than discarding an otherwise good substitution.
    """
    preceding = re.findall(r"[A-Za-z']+", masked[max(0, start - 40):start])
    if not preceding or preceding[-1].lower() not in _BARE_FORM_TRIGGERS:
        return replacement
    first, *rest = replacement.split()
    if first.endswith("s") and not first.endswith(("ss", "us", "is")):
        return " ".join([first[:-1]] + rest)
    return replacement


SIMPLIFY_PROMPT = (
    "You are rewriting sentences in an academic paper so a competent reader outside the "
    "subfield understands them on the first pass.\n"
    "TWO REQUIREMENTS:\n"
    "1. CONCEPT CEILING. Every sentence you produce must express at most 3 concepts, "
    "where a concept is one clause making one claim. Split a packed sentence into two "
    "or three short sentences. This is a hard ceiling.\n"
    "2. PLAIN VOCABULARY. Replace opaque academic words with wording a general technical "
    "reader knows: 'epistemic' -> 'about knowledge'; 'miscalibrated' -> 'out of step with "
    "how accurate the system actually is'; 'interrupts' -> 'breaks'; 'taxing' -> "
    "'burdening'. Prefer a short common word, or a few plain words, over one fancy word.\n"
    "PRECISION OUTRANKS BOTH. Keep any term the paper defines or the field uses as a term "
    "of art (provenance, reliance, persona, MCP, LLM). Never drop a qualification, never "
    "add a claim the original does not make, never change a number or a hedge into a "
    "certainty. If you cannot simplify without losing precision, set rewrite to the empty "
    "string.\n"
    "MECHANICAL RULES: preserve every [[N]] marker exactly as written, in a sensible "
    "position -- they are citations, math, and formatting. Never use LaTeX or any of the "
    "characters \\ { } $ & # _ ^ ~ %."
)
_FORBIDDEN_IN_REWRITE = re.compile(r"[\\{}$&#_^~%\x00]")


REWRITE_SCHEMA = {
    "type": "object", "additionalProperties": False,
    "properties": {"rewrites": {"type": "array", "items": {
        "type": "object", "additionalProperties": False,
        "properties": {"id": {"type": "integer"}, "rewrite": {"type": "string"},
                       "why": {"type": "string"}},
        "required": ["id", "rewrite", "why"]}}},
    "required": ["rewrites"],
}


def _rewrite_with_model(items, prompt, payload_for, gate, model, batch_size, label):
    """Shared plumbing for the sentence rewriters.

    Batching matters: a whole manuscript of sites overflows one response, and a truncated
    reply silently drops every decision after the cut. A failed batch leaves its sites
    unchanged rather than aborting the run.

    payload_for(index, item) builds one request row; gate(rewrite, item) returns a reason
    to reject or None. Returns {index: (rewrite, why, original, previous)}.
    """
    try:
        from openai import OpenAI
    except ImportError:
        print("openai package not installed; skipping.", file=sys.stderr)
        return {}
    key = _openai_api_key()
    if not key:
        print("No OpenAI key; skipping.", file=sys.stderr)
        return {}

    client = OpenAI(api_key=key)
    accepted, rejected = {}, Counter()
    for begin in range(0, len(items), batch_size):
        chunk = items[begin:begin + batch_size]
        payload = [payload_for(begin + i, item) for i, item in enumerate(chunk)]
        try:
            response = client.responses.create(
                model=model, reasoning={"effort": "medium"}, max_output_tokens=16000,
                input=[{"role": "developer", "content": prompt},
                       {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}],
                text={"format": {"type": "json_schema", "name": "rewrites",
                                 "strict": True, "schema": REWRITE_SCHEMA}},
            )
            data = json.loads(response.output_text)
        except Exception as e:
            print(f"  batch {begin // batch_size + 1} failed ({type(e).__name__}: {e}); "
                  "those sites are left unchanged.", file=sys.stderr)
            continue

        for r in data.get("rewrites", []):
            idx = r["id"]
            if not (0 <= idx < len(items)) or not r["rewrite"].strip():
                rejected["model declined"] += 1
                continue
            item = items[idx]
            rewrite = _from_markers(r["rewrite"].strip())
            problem = gate(rewrite, item)
            if problem:
                rejected[problem] += 1
                continue
            accepted[idx] = (rewrite, r["why"], item[2], item[4] if len(item) > 4 else "")
        print(f"  {label} {min(begin + batch_size, len(items))}/{len(items)}, "
              f"{len(accepted)} passed mechanical gates")

    if rejected:
        print("  rejected: " + ", ".join(f"{n}x {k}" for k, n in rejected.most_common()))
    return accepted


def llm_simplify_sentences(items, model=DEFAULT_LLM_MODEL, batch_size=12, max_concepts=3):
    """Rewrite over-packed sentences. Returns {index: (rewrite, why)} after verification."""
    accepted = _rewrite_with_model(
        items, SIMPLIFY_PROMPT,
        lambda i, item: {"id": i, "sentence": _to_markers(item[2]), "concepts": item[3]},
        lambda rw, item: _gate_rewrite(rw, item[2], max_concepts, max_growth=2.0),
        model, batch_size, "rewrote")
    return llm_verify_faithful(accepted, model=model)


def llm_decontrast_sentences(items, model=DEFAULT_LLM_MODEL, batch_size=10, max_concepts=3):
    """Rewrite contrastive sentences into direct positive statements.

    A rewrite is rejected unless the contrast detector finds nothing left in it, so one
    that merely reshuffles the negation cannot pass.
    """
    accepted = _rewrite_with_model(
        items, DECONTRAST_PROMPT,
        lambda i, item: {"id": i, "previous": _to_markers(item[4]),
                         "sentence": _to_markers(item[2]), "construction": item[3]},
        lambda rw, item: _gate_rewrite(rw, item[2], max_concepts, forbid_contrast=True),
        model, batch_size, "screened")
    return llm_verify_faithful(accepted, model=model)


def _readable(text):
    """Collapse placeholders and whitespace so a span prints legibly in the report."""
    return re.sub(r"\s+", " ", re.sub(r"\x00\d+\x00", "~", text)).strip()


DECONTRAST_PROMPT = (
    "You are removing contrastive framing from an academic paper. Contrastive framing "
    "says what something is NOT, or sets up a rejected alternative, which makes the "
    "reader hold two versions at once. State directly what IS the case.\n"
    "You are given `previous` for context and `sentence` to rewrite. Rewrite ONLY "
    "`sentence`. `previous` is shown because the negation often depends on it: in "
    "'The response is uniform.' / 'Its three clauses are not.', the second sentence "
    "must become a positive statement that spells out what the clauses actually are.\n"
    "REMOVE: 'not X but Y', 'not only X but also Y', 'rather than', 'instead of', 'as "
    "opposed to', 'far from', 'less X than Y', bare trailing negations ('...are not.'), "
    "and contrastive openers ('Instead,', 'Rather,', 'However,', 'Yet,', 'But').\n"
    "KEEP EVERYTHING TRUE: never drop a qualification, a hedge, or a number, and never "
    "add a claim the original does not make. A negation that carries real technical "
    "content ('the tiers denote source authority, not correctness') may be kept if "
    "removing it would lose the distinction -- in that case return an empty rewrite.\n"
    "Every sentence you produce must express at most 3 concepts. Preserve every [[N]] "
    "marker exactly. Never use LaTeX or the characters \\ { } $ & # _ ^ ~ %."
)


def _gate_rewrite(rewrite, original, max_concepts, forbid_contrast=False, max_growth=2.5):
    """Mechanical checks every rewrite must survive. Returns a reason to reject, or None.

    max_growth is looser for decontrast than for simplify: turning "not X but Y" into a
    positive statement often needs to name what X was, which costs words.
    """
    if _FORBIDDEN_IN_REWRITE.sub("", rewrite) != rewrite.replace("\x00", ""):
        return "introduced LaTeX"
    if sorted(re.findall(r"\x00(\d+)\x00", rewrite)) != \
       sorted(re.findall(r"\x00(\d+)\x00", original)):
        return "lost a citation/math span"
    worst = max((count_concepts(s[2]) for s in split_sentences(rewrite)), default=99)
    if worst > max_concepts:
        return f"still over ceiling ({worst})"
    if len(rewrite) > len(original) * max_growth:
        return "ballooned in length"
    if forbid_contrast:
        still = detect_contrast(rewrite)
        if still:
            return f"still contrastive ({still})"
    return None


def llm_verify_faithful(candidates, model=DEFAULT_LLM_MODEL, batch_size=10):
    """Second-pass check that each rewrite preserves meaning. Returns the surviving set.

    The mechanical gates cannot see semantics: they happily passed a rewrite that turned
    "Its three clauses are not [uniform]" into "Its three clauses express ... uniformity".
    Removing a negation is exactly the edit most likely to invert meaning, so every
    rewrite is re-checked against its original by a separate, adversarially framed call.
    """
    try:
        from openai import OpenAI
    except ImportError:
        return candidates
    key = _openai_api_key()
    if not key:
        return candidates

    schema = {
        "type": "object", "additionalProperties": False,
        "properties": {"checks": {"type": "array", "items": {
            "type": "object", "additionalProperties": False,
            "properties": {"id": {"type": "integer"}, "faithful": {"type": "boolean"},
                           "problem": {"type": "string"}},
            "required": ["id", "faithful", "problem"]}}},
        "required": ["checks"],
    }
    client = OpenAI(api_key=key)
    items = list(candidates.items())
    survivors, killed = {}, []

    for begin in range(0, len(items), batch_size):
        chunk = items[begin:begin + batch_size]
        payload = [{"id": begin + i, "previous": _readable(prev),
                    "original": _readable(original), "rewrite": _readable(rewrite)}
                   for i, (_, (rewrite, _why, original, prev)) in enumerate(chunk)]
        try:
            response = client.responses.create(
                model=model, reasoning={"effort": "medium"}, max_output_tokens=8000,
                input=[{"role": "developer", "content": VERIFY_PROMPT},
                       {"role": "user", "content": json.dumps(payload, ensure_ascii=False)}],
                text={"format": {"type": "json_schema", "name": "checks",
                                 "strict": True, "schema": schema}},
            )
            checks = json.loads(response.output_text).get("checks", [])
        except Exception as e:
            print(f"  verification failed ({type(e).__name__}); dropping this batch to "
                  "be safe.", file=sys.stderr)
            continue
        for c in checks:
            pos = c["id"] - begin
            if not (0 <= pos < len(chunk)):
                continue
            idx, (rewrite, why, original, prev) = chunk[pos]
            if c["faithful"]:
                survivors[idx] = (rewrite, why)
            else:
                killed.append((_readable(original), _readable(rewrite), c["problem"]))

    print(f"  faithfulness check: {len(survivors)} of {len(items)} survived")
    for original, rewrite, problem in killed:
        print(f"    REJECTED {original[:70]}")
        print(f"          -> {rewrite[:70]}")
        print(f"             {problem[:100]}")
    return survivors


def _to_markers(text):
    return re.sub(r"\x00(\d+)\x00", r"[[\1]]", text)


def _from_markers(text):
    return re.sub(r"\[\[\s*(\d+)\s*\]\]", lambda m: f"\x00{m.group(1)}\x00", text)


def _match_case(original, replacement):
    if original.isupper():
        return replacement.upper()
    if original[:1].isupper():
        return replacement[:1].upper() + replacement[1:]
    return replacement


def _revise_sentences(args, src, out_path, text, opaque_envs):
    """The sentence-rewriting goals: simplify and decontrast.

    Split out of cmd_revise because it shares only argument handling with the word-level
    goals: different masking, different unit of change, different reporting.
    """
    masked, spans = mask_latex(
        text, extra_envs=SENTENCE_SAFE_ENVS + FORMAL_ENVS + tuple(opaque_envs),
        extra_cmds=SENTENCE_SAFE_CMDS)
    comment_ids = comment_span_ids(spans)
    total = len(split_sentences(masked))
    if args.goal == "decontrast":
        packed = shortlist_contrast(masked, comment_ids=comment_ids)
        print(f"{len(packed)} of {total} sentences in {src.name} use contrastive framing.")
    else:
        packed = shortlist_sentences(masked, max_concepts=args.max_concepts,
                                     comment_ids=comment_ids)
        print(f"{len(packed)} of {total} sentences in {src.name} carry more than "
              f"{args.max_concepts} concepts.")
    if not packed or args.no_llm:
        out_path.write_text(text, encoding="utf-8")
        print(f"No changes applied; wrote {out_path.name}")
        return

    rewriter = (llm_decontrast_sentences if args.goal == "decontrast"
                else llm_simplify_sentences)
    rewrites = rewriter(packed, model=args.model, max_concepts=args.max_concepts)

    revised, changes = masked, []
    for idx in sorted(rewrites, key=lambda i: -packed[i][0]):
        start, end, original, note = packed[idx][:4]
        rewrite, why = rewrites[idx]
        # A sentence span carries the whitespace that separated it from its neighbours;
        # splicing in a stripped rewrite would weld it to the previous sentence
        # ("workforce.We ask").
        lead = original[:len(original) - len(original.lstrip())]
        trail = original[len(original.rstrip()):]
        revised = revised[:start] + lead + rewrite.strip() + trail + revised[end:]
        changes.append((original, rewrite, note, why))

    out_path.write_text(unmask_latex(revised, spans), encoding="utf-8")
    print(f"\nRewrote {len(changes)} sentence(s). Source untouched; wrote {out_path.name}\n")
    for original, rewrite, note, why in changes:
        after = max((count_concepts(s[2]) for s in split_sentences(rewrite)), default=0)
        print(f"  [{note} concepts -> {after}]")
        print(f"    BEFORE {_readable(original)[:200]}")
        print(f"    AFTER  {_readable(rewrite)[:200]}")
    if args.report:
        Path(args.report).write_text(json.dumps(
            [{"before": _readable(o), "after": _readable(r), "concepts_before": c,
              "why": w} for o, r, c, w in changes], indent=1), encoding="utf-8")
        print(f"\nWrote change report to {args.report}")


def cmd_revise(args):
    src = Path(args.tex)
    out_path = Path(args.out) if args.out else src.with_suffix(".revised.tex")
    if out_path.resolve() == src.resolve():
        sys.exit("Refusing to write over the source file; choose a different --out.")

    text = src.read_text(encoding="utf-8")
    opaque_envs = [e.strip() for e in (getattr(args, "opaque_env", "") or "").split(",") if e.strip()]

    if args.goal in ("simplify", "decontrast"):
        return _revise_sentences(args, src, out_path, text, opaque_envs)

    masked, spans = mask_latex(text, extra_envs=FORMAL_ENVS + tuple(opaque_envs))
    vocab = load_lookup_vocab(args.vocab)

    if args.goal == "precise":
        shortlist = {w: [] for w in shortlist_precision(masked)}
        print(f"{len(shortlist)} vague word(s) in {src.name} that the text may pin down.")
    else:
        shortlist = shortlist_revisions(masked, vocab, rare_max=args.rare_max,
                                        min_support=args.min_support)
        print(f"{len(shortlist)} word(s) in {src.name} are off-register vs your corpus.")
    if not shortlist:
        return

    # One decision per (word, sentence): the same word may be right in one sentence and
    # wrong in another, but re-screening an identical site would just cost tokens.
    proposals, sites, seen = [], [], {}
    for word, opts in shortlist.items():
        for m in re.finditer(rf"\b{re.escape(word)}\b", masked, re.IGNORECASE):
            sentence = _sentence_for(masked, m)
            key = (word, sentence)
            if key not in seen:
                seen[key] = len(proposals)
                proposals.append((word, sentence, opts))
            sites.append((m.start(), m.end(), word, seen[key]))
    print(f"{len(sites)} occurrence(s), {len(proposals)} distinct site(s) "
          f"to screen via {args.model} ...")

    decisions = ({} if args.no_llm else
                 llm_screen_revisions(proposals, model=args.model, goal=args.goal))

    edits, changes = [], []
    for start, end, word, idx in sites:
        key = (word, proposals[idx][1])
        if key in decisions:
            replacement, why = decisions[key]
            original = masked[start:end]
            final = _match_case(original, _fix_agreement(masked, start, replacement))
            edits.append((start, end, final))
            changes.append((original, final, proposals[idx][1], why))

    revised = masked
    for start, end, replacement in sorted(edits, key=lambda e: -e[0]):
        revised = revised[:start] + replacement + revised[end:]

    out_path.write_text(unmask_latex(revised, spans), encoding="utf-8")
    print(f"\nApplied {len(changes)} change(s). Source left untouched; wrote {out_path.name}\n")
    for original, replacement, sentence, why in changes:
        print(f"  {original} -> {replacement}")
        print(f"      {sentence[:110]}")
        print(f"      {why}")
    if args.report:
        Path(args.report).write_text(json.dumps(
            [{"from": o, "to": r, "sentence": s, "why": w} for o, r, s, w in changes],
            indent=1), encoding="utf-8")
        print(f"\nWrote change report to {args.report}")


def cmd_build(args):
    texts = extract_text_from_pdfs(args.pdf_dir, x_tolerance=args.x_tolerance)
    if not texts:
        print("No text extracted -- nothing to build.", file=sys.stderr)
        sys.exit(1)
    vocab = build_vocabulary(texts)
    if args.merge:
        base = load_vocab(args.base)
        before = len(base["term_freq"])
        vocab = merge_vocabs(base, vocab)
        print(f"Merged into existing vocabulary: {before} -> {len(vocab['term_freq'])} terms, "
              f"{vocab['num_docs']} papers total.")
    out_path = args.out or VOCAB_SIDECAR
    save_vocab(vocab, out_path)
    print("Future 'suggest'/'top' runs from this script will use this vocab automatically.")


def cmd_suggest(args):
    vocab = load_lookup_vocab(args.vocab)
    llm_candidates = {}
    if args.llm:
        llm_candidates = get_llm_candidates(args.word, context=args.context,
                                            model=args.model, n=max(args.n, 10))
    result = suggest_synonyms(args.word, vocab, top_n=args.n, llm_candidates=llm_candidates)

    origin = "WordNet + " + args.model if llm_candidates else "WordNet"
    print(f"\nYour word: '{args.word}'  (appears {result['input_word_freq']}x in your corpus)")
    if args.context:
        print(f"Context: {args.context}")
    print(f"Candidates from: {origin}\n")

    if result["found"]:
        print("Backed by your papers (ranked by your own usage):")
        for term, count, docs, srcs, why in result["found"]:
            tag = "+".join(srcs)
            print(f"  {term:<22} {count:>4}x in {docs:>2} paper(s)  [{tag}]")
            if why:
                print(f"      {why}")
    else:
        print("No candidate for this word appears anywhere in your corpus.")

    if result["unseen"]:
        print("\nNot found in your papers (use with care):")
        for term, _, _, srcs, why in result["unseen"]:
            tag = "+".join(srcs)
            print(f"  {term:<38}  [{tag}]")
            if why:
                print(f"      {why}")
    print()


def cmd_top(args):
    vocab = load_vocab(args.vocab)
    items = top_terms(vocab, n=args.n, min_docs=args.min_docs)
    print(f"\nTop {len(items)} terms across {vocab['num_docs']} paper(s) "
          f"(min. {args.min_docs} paper(s) using the term):\n")
    for term, count in items:
        docs = vocab["doc_freq"].get(term, 0)
        print(f"  {term:<30} {count:>4}x  ({docs} paper(s))")
    print()


def cmd_prune(args):
    vocab = load_vocab(args.vocab)
    before = len(vocab["term_freq"])
    pruned = prune_vocab(vocab, strategy=args.strategy, fraction=args.fraction)
    after = len(pruned["term_freq"])
    print(f"Pruned '{args.strategy}': {before} -> {after} terms "
          f"({100 * after / before:.1f}% kept, {before - after} dropped)")
    save_vocab(pruned, args.out or VOCAB_SIDECAR)


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="command", required=True)

    p_build = sub.add_parser("build", help="Build vocabulary from a folder of PDFs")
    p_build.add_argument("--pdf-dir", required=True, help="Folder containing PDF papers")
    p_build.add_argument("--out", default=None, help="Output vocab JSON file (default: vocab.json next to this script)")
    p_build.add_argument("--merge", action="store_true",
                         help="Add these PDFs to the existing vocabulary instead of replacing it")
    p_build.add_argument("--base", default=None,
                         help="Vocab to merge into (default: sidecar vocab.json, else embedded)")
    p_build.add_argument("--x-tolerance", type=float, default=1.5,
                         help="Char-gap threshold for word splitting in PDFs (default: 1.5; "
                              "raise if words are being split apart, lower if they run together)")
    p_build.set_defaults(func=cmd_build)

    p_suggest = sub.add_parser("suggest", help="Suggest corpus-backed synonyms for a word")
    p_suggest.add_argument("--vocab", default=None, help="Vocab JSON file (default: sidecar vocab.json, else embedded)")
    p_suggest.add_argument("--word", required=True, help="Word to find synonyms for")
    p_suggest.add_argument("--n", type=int, default=8, help="Max synonyms to show")
    p_suggest.add_argument("--llm", action="store_true",
                           help="Also ask an OpenAI model for candidates, then rank them by "
                                "your corpus usage (needs OPENAI_API_KEY or the conf file)")
    p_suggest.add_argument("--context", default=None,
                           help="The sentence you're writing, so the model judges fit in situ")
    p_suggest.add_argument("--model", default=DEFAULT_LLM_MODEL,
                           help=f"OpenAI model for --llm (default: {DEFAULT_LLM_MODEL})")
    p_suggest.set_defaults(func=cmd_suggest)

    p_top = sub.add_parser("top", help="Show most common terms in the vocabulary")
    p_top.add_argument("--vocab", default=None, help="Vocab JSON file (default: sidecar vocab.json, else embedded)")
    p_top.add_argument("--n", type=int, default=30, help="How many terms to show")
    p_top.add_argument("--min-docs", type=int, default=1, help="Only show terms appearing in at least this many papers")
    p_top.set_defaults(func=cmd_top)

    p_prune = sub.add_parser("prune", help="Shrink the vocabulary to the terms that matter")
    p_prune.add_argument("--vocab", default=None, help="Vocab to prune (default: sidecar vocab.json, else embedded)")
    p_prune.add_argument("--out", default=None, help="Where to write the pruned vocab (default: overwrite vocab.json)")
    p_prune.add_argument("--strategy", choices=("suggestible", "unigrams", "impact"), default="suggestible",
                         help="suggestible: WordNet single words only, the only terms 'suggest' can return "
                              "(default); unigrams: all single words; impact: top --fraction by frequency x "
                              "paper breadth, which does drop real corpus words")
    p_prune.add_argument("--fraction", type=float, default=0.10,
                         help="Fraction of terms to keep, 'impact' strategy only (default: 0.10)")
    p_prune.set_defaults(func=cmd_prune)

    p_rev = sub.add_parser("revise", help="Write a revised COPY of a .tex, aligned to your corpus")
    p_rev.add_argument("--tex", required=True, help="Source .tex file (never modified)")
    p_rev.add_argument("--out", default=None, help="Output file (default: <name>.revised.tex)")
    p_rev.add_argument("--vocab", default=None, help="Vocab to judge against (default: full, else sidecar)")
    p_rev.add_argument("--model", default=DEFAULT_LLM_MODEL, help=f"OpenAI model (default: {DEFAULT_LLM_MODEL})")
    p_rev.add_argument("--rare-max", type=int, default=2,
                       help="Flag words your corpus uses at most this often (default: 2)")
    p_rev.add_argument("--min-support", type=int, default=5,
                       help="A replacement needs at least this many corpus uses (default: 5)")
    p_rev.add_argument("--max-concepts", type=int, default=3,
                       help="Hard ceiling on claims per sentence, simplify goal (default: 3)")
    p_rev.add_argument("--goal", choices=("precise", "register", "simplify", "decontrast"), default="precise",
                       help="precise: replace vague wording with wording that names what "
                            "actually happens, so readers grasp it faster (default). "
                            "register: match your corpus's own word choices. "
                            "simplify: split over-packed sentences and plain out opaque "
                            "vocabulary, keeping every technical term. "
                            "decontrast: replace 'not X but Y' framing, including "
                            "negations that point back at the previous sentence, with "
                            "direct positive statements")
    p_rev.add_argument("--opaque-env", default=None,
                       help="Comma-separated extra environment names to freeze entirely "
                            "(use for a paper's own spec/code environments)")
    p_rev.add_argument("--no-llm", action="store_true",
                       help="Shortlist only, apply nothing (no API calls, writes an unchanged copy)")
    p_rev.add_argument("--report", default=None, help="Also write a JSON report of every change")
    p_rev.set_defaults(func=cmd_revise)

    args = parser.parse_args()
    args.func(args)


if __name__ == "__main__":
    main()
